def average_pool_via_conv(x: torch.Tensor, kernel_size: int) -> torch.Tensor:
    channels = x.shape[1]
    weights = x.new_full(
        (channels, 1, kernel_size),
        1.0 / kernel_size,
    )
    return F.conv1d(
        x,
        weights,
        stride=kernel_size,
        groups=channels,
    )
